window.WORKSHOP = {"title": "ZPE bez pośpiechu", "date": "28.09.2026", "event_date": "4 listopada 2026", "version": 3, "sources": [["Wyszukiwanie materiałów", "https://zpe.gov.pl/a/wyszukiwanie-materialow/DB4RUK55O", "Instrukcja wyszukiwania i filtrów; punkt odniesienia dla karty 2."], ["Ulubione", "https://zpe.gov.pl/a/ulubione/DE1FP3VBC", "Zapis przez serce, powrót przez Katalog → Ulubione; źródło dwóch ilustracji. Funkcja wymaga zalogowania."], ["Poradnik dla nauczycieli", "https://zpe.gov.pl/platforma-edukacyjna", "Główna nawigacja do aktualnie dostępnych instrukcji."], ["Filmy i instrukcje", "https://zpe.gov.pl/filmy-i-instrukcje", "Dalsza pomoc po warsztacie; różne generacje poradników mogą pokazywać inne ekrany."], ["Dodawanie materiałów do kursu", "https://zpe.gov.pl/a/dodawanie-materialow-do-kursu/D2F5EFRLV", "Ścieżka pokazu: Udostępnij → Platforma edukacyjna → Nowy kurs."], ["Zapisywanie uczniów", "https://zpe.gov.pl/a/zapisywanie-uczniow/D2UOTPKJV", "Publikacja kursu i przypisywanie uczniów; konta szkolne i prywatne mają odmienny kontekst klas."], ["Monitorowanie postępów", "https://zpe.gov.pl/a/monitorowanie-postepow/D8OONO24C", "Raport w zakładce Analiza. Czas wyświetlania nie jest pomiarem uwagi ucznia."], ["Generator Kart Pracy", "https://zpe.gov.pl/a/generator-kart-pracy/D9D7YmwXP", "Możliwość dalszej nauki. Poza obowiązkową częścią warsztatu."], ["Nauczanie jawne", "https://metodyka.covepolska.pl/metoda-nauczanie-jawne.html", "Małe kroki, modelowanie i samodzielna próba. Adaptacja do dorosłych."], ["Przykłady rozwiązane", "https://metodyka.covepolska.pl/metoda-przyklady-rozwiazane.html", "Pełny model, pomoc stopniowo wycofywana, nowe zadanie."], ["Tutoring rówieśniczy", "https://metodyka.covepolska.pl/metoda-peer-tutoring.html", "Ćwiczenie poznanej procedury w parach ze zmianą ról."], ["Wzorzec struktury lekcji", "https://informatyka.szkolamistrzow.info/teacher/lesson/08/", "Cele, przygotowanie, etapy, pytania prowadzącego, trudności i sprawdzenie."]], "knowledge": [{"group": "Zacznij tutaj", "title": "Wyszukiwanie i wybór materiału", "live": true, "purpose": "Znajdź jeden fragment pasujący do celu lekcji, poziomu uczniów i dostępnego czasu.", "path": "Katalog → wyszukiwarka → etap edukacyjny, przedmiot lub podstawa programowa → podgląd materiału.", "practice": "Skróć zapytanie, gdy nie ma wyników. Otwórz materiał i wskaż dokładny fragment, zamiast zadawać uczniom cały zasób.", "caution": "Filtry i układ ekranu mogą wyglądać inaczej niż w starszym poradniku. Wybór materiału zawsze wymaga oceny nauczyciela.", "source": "Poradnik: logowanie, wyszukiwanie, udostępnianie i tworzenie materiałów"}, {"group": "Zacznij tutaj", "title": "Ulubione i porządkowanie zasobów", "live": true, "purpose": "Zachowaj materiał na swoim koncie i wróć do niego bez ponownego wyszukiwania.", "path": "Otwarty materiał → serce / Dodaj do ulubionych → Katalog → Ulubione.", "practice": "Zapisz tytuł, pełny link i nazwę fragmentu również w planie lekcji. Materiały z kilku przedmiotów można porządkować w teczkach.", "caution": "Zakładka przeglądarki i Ulubione ZPE to dwie różne rzeczy. Drugie kliknięcie serca może usunąć zapis.", "source": "Poradnik: logowanie, wyszukiwanie, udostępnianie i tworzenie materiałów"}, {"group": "Praca z uczniami", "title": "Udostępnianie: link, grupa, kod lub kurs", "live": true, "purpose": "Dobierz sposób przekazania materiału do tego, czy potrzebujesz tylko dostępu, czy także wyników uczniów.", "path": "Otwarty materiał → Udostępnij → wybór dostępnego trybu: istniejąca lub nowa grupa, kod/link albo praca na platformie.", "practice": "Do szybkiego użycia wystarczy bezpośredni link i jasne polecenie. Jeśli chcesz raportów, przygotuj pracę na platformie i przypisz właściwych użytkowników.", "caution": "Samo wysłanie zwykłego linku nie tworzy zadania i nie gwarantuje raportu. Nie każde ćwiczenie zapisuje wyniki w ten sam sposób.", "source": "Udostępnianie materiałów, ich segregacja i sprawdzenie wyników uczniów"}, {"group": "Praca z uczniami", "title": "Klasy i własne grupy", "live": false, "purpose": "Udostępniaj kolejne materiały tej samej grupie i zarządzaj uczestnikami.", "path": "Klasy/Grupy → wybór klasy z systemu szkolnego albo Utwórz grupę → dodanie uczestników.", "practice": "Własną grupę można wykorzystać ponownie. Klasy pochodzące z SIO i grupy utworzone ręcznie mają inne zasady zarządzania.", "caution": "Nauczyciel nie edytuje danych klasy zaimportowanej z SIO. Nie pokazuj na szkoleniu danych prawdziwych uczniów.", "source": "Zarządzanie użytkownikami; Tworzenie grup i zarządzanie nimi"}, {"group": "Sprawdzanie", "title": "Wyniki i decyzja nauczyciela", "live": true, "purpose": "Zobacz odpowiedzi lub wyniki i zdecyduj, co wyjaśnić ponownie, komu pomóc i kto może przejść dalej.", "path": "Przypisany materiał lub kurs → wyniki / analiza → widok grupy i szczegóły podejścia.", "practice": "Najpierw sprawdź, czy uczeń miał dostęp i rozumiał polecenie. Dopiero potem interpretuj brak odpowiedzi lub niski wynik.", "caution": "Czas wyświetlania nie jest miarą uwagi. Raport ma wspierać decyzję dydaktyczną, a nie automatycznie oceniać zaangażowanie.", "source": "Udostępnianie materiałów…; Tworzenie ścieżek nauki; Zarządzanie materiałami"}, {"group": "Tworzenie", "title": "Generator kart pracy", "live": false, "purpose": "Zbuduj prostą, wielostronicową kartę z tekstem i grafikami, zapisz ją, pobierz lub udostępnij.", "path": "Generator Kart Pracy → nowa karta albo szablon → strony i elementy → zapis → podgląd / pobranie / udostępnienie.", "practice": "Zacznij od jednej strony i jednego celu. Najpierw przygotuj polecenie i oczekiwaną odpowiedź, potem dobieraj elementy.", "caution": "To rozszerzenie po szkoleniu. Podczas warsztatu szybszy będzie plan krótki fragment oparty na gotowym zasobie.", "source": "Zintegrowana Platforma Edukacyjna - Generator Kart Pracy"}, {"group": "Tworzenie", "title": "Kreator e-materiałów", "live": false, "purpose": "Twórz rozbudowane materiały z tekstem, multimediami, spisem treści i ćwiczeniami interaktywnymi.", "path": "Kreator → nowy projekt → ustawienia i spis treści → komponenty → podgląd → zapis i publikacja.", "practice": "Buduj małymi krokami: jedna sekcja, jedno ćwiczenie i próba na koncie testowym. Kreator obsługuje też wiele typów interakcji.", "caution": "Kreator jest rozbudowany i zasługuje na osobne szkolenie. Nie zaczynaj od niego, jeśli celem jest gotowy materiał w ciągu jednego spotkania.", "source": "Zintegrowana Platforma Edukacyjna - Kreator e-materiałów"}, {"group": "Planowanie", "title": "Ścieżki nauki", "live": false, "purpose": "Ułóż kilka materiałów w kolejności i określ warunki przechodzenia do kolejnych kroków.", "path": "Moje materiały → Utwórz ścieżkę → dodaj materiały → ustaw kolejność i warunki → zapisz → udostępnij.", "practice": "Używaj, gdy uczniowie mają pracować dłużej niż jedną lekcję lub różnym tempem. Sprawdź ścieżkę na koncie ucznia testowego.", "caution": "Próg procentowy lub przeczytanie zasobu nie dowodzi jeszcze zrozumienia. Dodaj zadanie wymagające odpowiedzi lub produktu.", "source": "Zintegrowana Platforma Edukacyjna - Tworzenie ścieżek nauki"}, {"group": "Komunikacja", "title": "Wiadomości i komunikator", "live": false, "purpose": "Przekazuj instrukcje, linki i pliki pojedynczym osobom, grupom lub klasom.", "path": "Funkcjonalności zaawansowane → Wiadomości albo Komunikator → odbiorca / kanał → treść i załącznik.", "practice": "W tytule podaj przedmiot i termin, a w wiadomości: co otworzyć, co zrobić i jak oddać efekt.", "caution": "Kanały publiczne, grupy prywatne i wiadomości bezpośrednie mają różny zakres widoczności. Nie przesyłaj danych wrażliwych.", "source": "Wysyłanie wiadomości; Zintegrowana Platforma Edukacyjna - Komunikator"}, {"group": "Dla zaawansowanych", "title": "Inne obiekty i funkcje zaawansowane", "live": false, "purpose": "Zarządzaj m.in. testami, ankietami, kursami, plikami, filmami, linkami i pakietami SCORM.", "path": "Funkcjonalności zaawansowane → zarządzanie materiałami → wybór typu obiektu → ustawienia → zapis / udostępnienie.", "practice": "Najpierw określ efekt dla ucznia i sposób sprawdzenia. Dopiero potem wybierz typ obiektu.", "caution": "Nazwy ekranów i dostępność funkcji zależą od roli oraz wersji platformy. Ten obszar wymaga osobnego ćwiczenia na koncie testowym.", "source": "Zarządzanie materiałami w funkcjonalnościach zaawansowanych"}], "parts": [{"n": 1, "title": "Modele pracy z technologią", "effect": "Rozumiem, co robi uczeń, co robi nauczyciel i po co w tej lekcji jest technologia.", "stages": [1]}, {"n": 2, "title": "ZPE krok po kroku", "effect": "Potrafię się zalogować, znaleźć, ocenić, zapisać i ponownie otworzyć materiał.", "stages": [2, 3, 4]}, {"n": 3, "title": "Pracownia: moja lekcja", "effect": "Mam gotowy fragment lekcji lub materiał, sprawdzony z partnerem i zapisany do użycia.", "stages": [6, 7, 9, 10, 11, 12]}], "pdf_guides": [{"title": "Poradnik praktyczny: od logowania do własnych materiałów", "pages": 19, "topics": ["logowanie i rejestracja", "wyszukiwanie i filtry", "udostępnianie", "teczki i własne materiały", "komunikacja"], "used": "Podstawa części wspólnej: logowanie, wyszukiwanie, Ulubione i dobór sposobu udostępnienia.", "file": "materialy-zrodlowe/01-poradnik-praktyczny-zpe.pdf"}, {"title": "Komunikator ZPE", "pages": 14, "topics": ["kanały publiczne", "grupy prywatne", "wiadomości bezpośrednie", "załączniki, audio i wideo", "wyszukiwanie i oznaczanie wiadomości"], "used": "Rozszerzenie po szkoleniu: organizowanie komunikacji w klasie i świadomy wybór widoczności.", "file": "materialy-zrodlowe/02-komunikator-zpe.pdf"}, {"title": "Udostępnianie materiałów i sprawdzanie wyników", "pages": 21, "topics": ["istniejąca i nowa grupa", "kod lub link", "praca na platformie", "segregowanie materiałów", "raporty i szczegółowe odpowiedzi"], "used": "Podstawa pokazu różnicy między zwykłym linkiem a zadaniem, z którego nauczyciel może otrzymać wyniki.", "file": "materialy-zrodlowe/03-udostepnianie-i-wyniki.pdf"}, {"title": "Generator Kart Pracy", "pages": 32, "topics": ["nowa karta i szablony", "strony i elementy", "zapis i filtrowanie", "pobieranie i udostępnianie", "edycja i usuwanie"], "used": "Rozszerzenie dla osób, które po warsztacie chcą zamienić plan lekcji w osobną kartę pracy.", "file": "materialy-zrodlowe/04-generator-kart-pracy.pdf"}, {"title": "Tworzenie ścieżek nauki", "pages": 11, "topics": ["dodawanie materiałów", "kolejne kroki", "warunki zaliczenia", "udostępnianie", "wyniki uczestników"], "used": "Rozszerzenie do pracy dłuższej niż jedna lekcja lub do pracy uczniów w różnym tempie.", "file": "materialy-zrodlowe/05-sciezki-nauki.pdf"}, {"title": "Zarządzanie użytkownikami", "pages": 10, "topics": ["klasy i grupy", "klasy z SIO", "lista użytkowników", "filtrowanie", "uprawnienia"], "used": "Źródło rozróżnienia między klasą zaimportowaną z SIO a własną grupą nauczyciela.", "file": "materialy-zrodlowe/06-zarzadzanie-uzytkownikami.pdf"}, {"title": "Jak utworzyć grupę i nią zarządzać", "pages": 4, "topics": ["utworzenie grupy", "dodawanie adresów e-mail", "usuwanie uczestnika", "usuwanie grupy", "filtrowanie użytkowników"], "used": "Krótka instrukcja pomocnicza do wielokrotnego udostępniania materiałów tej samej grupie.", "file": "materialy-zrodlowe/07-tworzenie-grupy.pdf"}, {"title": "Klasy i grupy - instrukcja rozszerzona", "pages": 23, "topics": ["tworzenie i opuszczanie grup", "dodawanie z klas i grup", "zaproszenia", "uczestnicy", "udostępnianie materiału grupie"], "used": "Rozszerzenie dla prowadzącego i nauczycieli planujących regularną pracę z tą samą grupą.", "file": "materialy-zrodlowe/08-klasy-i-grupy.pdf"}, {"title": "Wysyłanie wiadomości", "pages": 11, "topics": ["odebrane i wysłane", "wyszukiwanie wiadomości", "wiadomość do osoby", "wiadomość do grupy lub klasy", "załączniki i usuwanie"], "used": "Źródło prostego schematu wiadomości: co otworzyć, co zrobić, do kiedy i jak przekazać efekt.", "file": "materialy-zrodlowe/09-wysylanie-wiadomosci.pdf"}, {"title": "Kreator e-materiałów", "pages": 67, "topics": ["projekty i ustawienia", "spis treści", "komponenty i multimedia", "ćwiczenia interaktywne", "publikacja i dostępność"], "used": "Najszersze rozszerzenie. Na 4 listopada pokazujemy jego miejsce w ekosystemie, a nie pełną obsługę.", "file": "materialy-zrodlowe/10-kreator-e-materialow.pdf"}, {"title": "Zarządzanie materiałami w funkcjach zaawansowanych", "pages": 26, "topics": ["testy i ankiety", "kursy", "pliki, filmy i linki", "SCORM", "wyniki i statystyki"], "used": "Źródło mapy zaawansowanych obiektów oraz ostrzeżenia, że dostęp zależy od roli użytkownika.", "file": "materialy-zrodlowe/11-funkcje-zaawansowane.pdf"}], "extensions": {"1": [["Mapa 12 metod pracy z technologią", "#/wstep"], ["Pełny katalog metod COVE", "https://metodyka.covepolska.pl/"]], "2": [["Baza wiedzy: logowanie i organizacja pracy", "#/baza-wiedzy"]], "3": [["Baza wiedzy: wyszukiwanie i Ulubione", "#/baza-wiedzy"], ["Indeks 11 poradników PDF", "#/poradniki"]], "4": [["Jak pracować z klasą lub grupą", "#/baza-wiedzy"]], "6": [["Zestaw 8 sprawdzonych punktów startowych", "#/materialy"], ["Baza wiedzy: wyszukiwanie i dobór", "#/baza-wiedzy"]], "7": [["Generator Kart Pracy i Kreator - kiedy warto", "#/baza-wiedzy"]], "9": [["Katalog metod COVE", "https://metodyka.covepolska.pl/"]], "10": [["Udostępnianie, raporty i ścieżki nauki", "#/baza-wiedzy"], ["Przykład interpretacji raportu", "#/pokaz"]], "11": [["Karty uczestnika krok po kroku", "#/karty"]], "12": [["Wszystkie materiały po szkoleniu", "#/centrum-materialow"]]}, "resources": [{"id": "notatki", "kind": "ogólne", "subject": "Wspólny start / każdy przedmiot", "title": "Gdzie tego szukać? O notowaniu", "url": "https://zpe.gov.pl/a/gdzie-tego-szukac-o-notowaniu/DgDem0ria", "fragment": "Początek materiału: zestawienie form notatki (tabela, punkty, schemat).", "task": "Wybierz formę notatki do porównania dwóch rozwiązań. Zapisz dwie kolumny i uzasadnij wybór formy.", "evidence": "Uczeń wybiera tabelę lub inną uzasadnioną formę i podaje kryterium porównania.", "note": "Na warsztacie wykorzystujemy krótki fragment. Oprawa całego zasobu jest skierowana do młodszych uczniów."}, {"id": "sarmatyzm", "kind": "ogólne", "subject": "Język polski / historia, szkoła ponadpodstawowa", "title": "Orient a kultura sarmacka", "url": "https://zpe.gov.pl/a/wprowadzenie/D532MWKZ8", "fragment": "Wprowadzenie: trzy portrety i akapit o wpływach Wschodu i Zachodu.", "task": "Wskaż na ilustracjach dwa szczegóły stroju. Ułóż pytanie, które pomoże zbadać ich pochodzenie.", "evidence": "Dwie obserwacje i pytanie odróżnione od niepotwierdzonej hipotezy.", "note": "Dalsza część „Przeczytaj” może posłużyć do późniejszej weryfikacji hipotez."}, {"id": "procenty", "kind": "ogólne", "subject": "Matematyka / powtórzenie podstaw", "title": "Obliczenia procentowe. Część I", "url": "https://zpe.gov.pl/a/obliczenia-procentowe-czesc-i/DLiy0FUq5", "fragment": "Początkowe przypomnienie typów obliczeń procentowych; jeden przykład dobrany przez nauczyciela.", "task": "Po obejrzeniu przykładu oblicz 15% z 200 zł i wyjaśnij, od jakiej liczby liczysz procent.", "evidence": "30 zł oraz wskazanie 200 zł jako podstawy obliczenia.", "note": "Polecenie z kwotą 200 zł jest autorskim zadaniem warsztatu, nie cytatem z ZPE."}, {"id": "fotosynteza", "kind": "ogólne", "subject": "Biologia, szkoła ponadpodstawowa", "title": "Fotosynteza jako reakcja anaboliczna", "url": "https://zpe.gov.pl/a/wprowadzenie/D1ADAV8f6", "fragment": "Wprowadzenie: krótki opis fotosyntezy i lista celów.", "task": "Wypisz dwa substraty fotosyntezy i wskaż źródło energii. Powiedz, czego roślina nie pobiera w gotowej postaci.", "evidence": "Woda, dwutlenek węgla, energia światła; rozróżnienie substratów od wytwarzanych związków organicznych.", "note": "Zakres i język polecenia nauczyciel dostosowuje do swojej klasy."}, {"id": "poligrafia", "kind": "zawodowe", "subject": "Grafika i poligrafia / PGF.04", "title": "Przygotowanie materiałów do publikacji", "url": "https://zpe.gov.pl/a/przewodnik-dla-nauczyciela/D16iKRlNO", "fragment": "Przewodnik nauczyciela → Struktura e-materiału → „Przygotowanie publikacji elektronicznych” (plansza).", "task": "Wybierz jeden element planszy. Ułóż dwa pytania kontrolne dla osoby przygotowującej publikację.", "evidence": "Dwa pytania, odpowiedzi oparte na wskazanym elemencie oraz miejsce sprawdzenia.", "note": "Link otwiera przewodnik. Do własnej lekcji skopiuj adres wybranej planszy, a nie przewodnika."}, {"id": "transport", "kind": "zawodowe", "subject": "Transport / kierowca mechanik", "title": "Przygotowanie miejsca pracy kierowcy mechanika", "url": "https://zpe.gov.pl/a/przewodnik-dla-uczacego-sie/D1FAMRiKQ", "fragment": "Przewodnik → film instruktażowy „Przygotowanie miejsca pracy kierowcy mechanika”. Wybierz jedną czynność z filmu.", "task": "Po wybranym fragmencie zapisz dwie czynności przygotowawcze i uzasadnij ich kolejność.", "evidence": "Dwie czynności zgodne z filmem i uzasadnienie; nauczyciel weryfikuje poprawność zawodową.", "note": "To analiza materiału przy komputerze. Nie jest instruktażem uprawniającym do obsługi pojazdu."}, {"id": "logistyka", "kind": "zawodowe", "subject": "Logistyka / SPL.01", "title": "Dokumentacja magazynowa (obieg dokumentów)", "url": "https://zpe.gov.pl/a/wprowadzenie/DQ4p55Laj", "fragment": "Spis treści → „Dokumentacja w obrocie magazynowym” (infografika). Wybierz dwa dokumenty.", "task": "Dla dwóch wybranych dokumentów zapisz nazwę i sytuację, w której są potrzebne.", "evidence": "Dwie poprawne pary: dokument i zastosowanie; odniesienie do infografiki.", "note": "Materiał wskazuje stan prawny z 08.09.2023. Na warsztacie ćwiczymy wybór zasobu; aktualność przepisów zawodowych wymaga osobnej weryfikacji."}, {"id": "piekarstwo", "kind": "zawodowe", "subject": "Piekarstwo / SPC.03", "title": "Przygotowanie surowców i wytwarzanie ciast", "url": "https://zpe.gov.pl/a/podstawowe-zabiegi-przygotowawcze-surowcow-do-wytwarzania-ciast/DCrSaaRtm", "fragment": "Grafika interaktywna „Podstawowe zabiegi przygotowawcze surowców do wytwarzania ciast”; wybierz jeden zabieg.", "task": "Nazwij wybrany zabieg i wyjaśnij jego cel. Wskaż w materiale informację, na której opierasz odpowiedź.", "evidence": "Nazwa zabiegu, jego cel i odwołanie do opisu w grafice.", "note": "Dostępny jest także opis tekstowy. Nie trzeba przechodzić wszystkich zakładek."}], "fields": [["topic", "Temat mojej lekcji", "Np. Porównywanie dwóch sposobów notowania"], ["group", "Przedmiot i klasa", "Np. godzina wychowawcza, klasa 1 technikum"], ["need", "Co chcę ułatwić uczniom?", "Np. wybranie najważniejszych informacji"], ["goal", "Cel: po tym fragmencie uczeń potrafi…", "Jedna czynność, którą można zobaczyć lub usłyszeć"], ["title", "Tytuł materiału ZPE", "Tytuł wybranego zasobu"], ["url", "Link do materiału ZPE", "Wklej pełny adres zaczynający się od https://zpe.gov.pl/"], ["fragment", "Dokładny fragment", "Nagłówek, numer ćwiczenia albo początek i koniec filmu"], ["duration", "Kolejność działań ucznia", "Najpierw przykład, potem własna próba i sprawdzenie"], ["task", "Polecenie dla ucznia", "Co ma zrobić i co ma oddać lub powiedzieć?"], ["answer", "Oczekiwana odpowiedź lub produkt", "Po czym rozpoznasz poprawne wykonanie?"], ["check", "Jak sprawdzę efekt?", "Np. każdy pokazuje dwie odpowiedzi, omawiam jeden typowy błąd"], ["revision", "Co poprawiam po próbie z partnerem?", "Jedna konkretna zmiana polecenia lub czasu"], ["date", "Kiedy wykorzystam tę lekcję?", "Data lub dzień i klasa"], ["backup", "Plan bez internetu", "Np. wydruk wybranego fragmentu i to samo pytanie"], ["own", "Moje materiały i dodatkowe źródła", "Tytuł pliku lub pełny adres źródła; autor i warunki wykorzystania"], ["delivery", "Jak przekażę zadanie uczniom?", "Projektor, urządzenie na parę lub praca indywidualna; link albo przypisane zadanie"]], "example": {"topic": "Jak porównać dwie formy notatki?", "group": "Godzina wychowawcza, klasa 1 technikum", "need": "Uczniowie zapisują dużo tekstu, ale trudno im porównywać informacje.", "goal": "Dobiera formę notatki do porównania dwóch rzeczy i uzasadnia wybór.", "title": "Gdzie tego szukać? O notowaniu", "url": "https://zpe.gov.pl/a/gdzie-tego-szukac-o-notowaniu/DgDem0ria", "fragment": "Początek materiału: zestawienie „Tabela / Punkty / Schemat”.", "duration": "Porównanie dwóch przykładów, własna odpowiedź, rozmowa w parze i sprawdzenie uzasadnienia.", "task": "Porównaj notatkę w punktach z tabelą. Zapisz po jednej zalecie każdej formy. Wybierz formę do porównania dwóch telefonów i uzasadnij wybór jednym zdaniem.", "answer": "Dwie zalety związane z zastosowaniem. Np. punkty porządkują kolejne kroki, tabela ułatwia porównanie według tych samych cech. Wybór tabeli uzasadniony kryteriami porównania.", "check": "Każdy zapisuje wybór i uzasadnienie. Czytam trzy różne odpowiedzi; sprawdzamy, czy uzasadnienie odnosi się do celu.", "revision": "Doprecyzowanie: porównujemy telefony według ceny i czasu pracy baterii.", "date": "Najbliższa godzina wychowawcza; przed wyjściem wpisuję konkretną datę.", "backup": "Na kartce podaję trzy formy: tabela, punkty, schemat. Uczniowie wykonują to samo polecenie.", "own": "Dwa opisy telefonów przygotowane przez nauczyciela, bez danych uczniów.", "delivery": "Wyświetlam przykłady na projektorze. Każdy zapisuje odpowiedź, następnie porównuje ją z partnerem."}, "intro": {"title": "Lekcja, w której pracują uczniowie", "lede": "Laptop, iPad i ZPE nie zmieniają lekcji same z siebie. Zmieniają ją wtedy, gdy gotowy materiał przejmuje część podawania treści, a nauczyciel odzyskuje czas na rozmowę z uczniami w trakcie ich pracy.", "thesis": [{"icon": "🎤", "title": "Dziś najczęściej pracuje nauczyciel", "text": "W wykładzie uczniowie słuchają w jednym tempie. O tym, co zrozumieli, nauczyciel dowiaduje się zwykle dopiero z kartkówki."}, {"icon": "💻", "title": "Materiał może przejąć tłumaczenie", "text": "E-materiał ZPE ma tekst, ilustracje, filmy i ćwiczenia. Uczeń może go zatrzymać, cofnąć albo powiększyć. Część ćwiczeń sprawdza odpowiedź od razu."}, {"icon": "🧭", "title": "Nauczyciel odzyskuje czas", "text": "To nie jest przerwa dla nauczyciela. Chodzi między ławkami i siada przy uczniach, którzy utknęli. Na podstawie odpowiedzi całej klasy decyduje, co dalej."}], "caution": "Technologia nie jest metodą. Efekt zależy od zadania ucznia, informacji zwrotnej i od tego, co nauczyciel zrobi z odpowiedziami klasy. Przy każdej metodzie w katalogu COVE jest ocena siły dowodów.", "shifts": [["Wszyscy słuchają w jednym tempie.", "Każdy pracuje z materiałem we własnym tempie.", "Uczeń może zatrzymać film, wrócić do akapitu lub przejść dalej. Kto skończy wcześniej, dostaje zadanie trudniejsze, a nie czeka.", "360 e-learning; Mastery learning"], ["Pierwszy kontakt z treścią to wykład.", "Pierwszy kontakt to krótki materiał, a lekcja służy pracy nad problemem.", "Krótki film lub fragment e-materiału przed lekcją albo na jej początku. Na lekcji zostaje czas na zadania z nauczycielem.", "Flipped classroom; Blended learning"], ["Nauczyciel sprawdza prace po tygodniu.", "Uczeń dostaje informację zwrotną od razu.", "Ćwiczenie z automatycznym sprawdzaniem pokazuje błąd w chwili jego popełnienia. Najczęstszy błąd nauczyciel omawia z całą klasą.", "Przypominanie i powroty; Ocenianie kształtujące"], ["Jedna droga dostępu: słuchanie.", "Kilka dróg do tego samego celu.", "Ten sam zasób często ma tekst, grafikę i nagranie. Uczeń wybiera drogę dostępu, ale cel jest wspólny dla całej klasy.", "UDL"], ["Nauczyciel przy tablicy.", "Nauczyciel przy uczniach.", "Gdy materiał tłumaczy, nauczyciel siada przy 3-4 wcześniej wybranych osobach i notuje, gdzie się zatrzymały.", "Modelowanie; Metapoznanie"], ["Na koniec lekcji uczeń ma notatkę.", "Na koniec lekcji uczeń ma decyzję lub produkt.", "Materiał staje się źródłem danych. Uczniowie korzystają z niego, rozwiązując przypadek, porównując odpowiedzi w parze i rozmawiając całą klasą.", "Problem, przypadek, projekt; Współpraca; Nauczanie dialogowe"]], "compare": {"A": [[25, "n", "Wykład z prezentacją; uczniowie przepisują slajdy"], [8, "n", "Pytania do chętnych"], [5, "u", "Jedno zadanie z podręcznika"], [2, "n", "Zadanie domowe"]], "B": [[4, "u", "Przypomnij bez notatek"], [5, "n", "Pokaz jednej decyzji"], [12, "u", "Praca własna z ZPE"], [3, "k", "Jedno pytanie do wszystkich"], [10, "p", "Przypadek w parach"], [4, "k", "Rozmowa klasy"], [2, "u", "Karta wyjścia"]]}, "compare_note": "To plan, a nie pomiar. Porównanie pokazuje, kto pracuje w kolejnych minutach. W wersji B nauczyciel mówi do całej klasy przez około , a przez  pracy własnej i pracy w parach jest przy uczniach.", "lesson": {"label": "Technik logistyk, klasa 2: Który dokument magazynowy?", "context": "Lekcja : około  organizacji,  pracy. Jeden laptop lub iPad na ucznia (możliwa też praca jednym urządzeniem w parze). Materiał ZPE „Dokumentacja magazynowa”, fragment „Dokumentacja w obrocie magazynowym” (infografika).", "url": "https://zpe.gov.pl/a/wprowadzenie/DQ4p55Laj", "goal": "Uczeń dobiera dokument (PZ, WZ, MM, RW, PW) do sytuacji magazynowej i uzasadnia decyzję przy przyjęciu dostawy z rozbieżnością.", "steps": [{"title": "Przypomnij bez notatek", "method": "Przypominanie i powroty", "teacher": "Wyświetla trzy krótkie pytania z poprzedniej lekcji o przyjęciu i wydaniu towaru. Po  pokazuje klucz.", "students": "Odpowiadają na kartce bez zeszytu i ekranu. Sami sprawdzają odpowiedzi z kluczem i zaznaczają, czego nie pamiętali.", "device": "Urządzenia zamknięte."}, {"title": "Pokaz jednej decyzji", "method": "Modelowanie", "teacher": "Na jednym przykładzie myśli na głos: „Skąd przychodzi towar? Spoza firmy czy z jej wnętrza? Przyjmuję go czy wydaję?” Dochodzi w ten sposób do PZ.", "students": "Zapisują dwa pytania kontrolne: kierunek ruchu towaru (przyjęcie czy wydanie) oraz to, czy druga strona jest spoza firmy, czy z wewnątrz.", "device": "Ekran nauczyciela; uczniowie piszą na kartce."}, {"title": "Praca własna z ZPE", "method": "360 e-learning; UDL", "teacher": "Podaje bezpośredni link. Chodzi po sali z listą 3-4 osób, przy których siada najpierw. Notuje, na którym pytaniu kto się zatrzymał. Nie tłumaczy całej klasie.", "students": "Otwierają infografikę i we własnym tempie odpowiadają na pięć pytań o PZ, WZ, MM, RW i PW. Kto skończy, układa własną sytuację do jednego dokumentu dla kolegi.", "device": "Laptop lub iPad: powiększenie, powrót do fragmentu, opis tekstowy. Wydruk infografiki dla osób, którym ekran przeszkadza."}, {"title": "Jedno pytanie do wszystkich", "method": "Ocenianie kształtujące; Mastery learning", "teacher": "Pyta: „Magazynier wydaje materiał na produkcję we własnej firmie. Jaki dokument? A) WZ, B) RW, C) MM, D) PZ”. Wszyscy pokazują odpowiedź w tej samej chwili. Liczy odpowiedzi.", "students": "Podnoszą kartkę z literą. Poprawna odpowiedź to B, czyli RW. Typowy błąd to WZ, bo „wydanie” kojarzy się z wydaniem zewnętrznym.", "device": "Kartki z literami albo ankieta; urządzenia zamknięte."}, {"title": "Przypadek w parach", "method": "Problem, przypadek, projekt; Współpraca", "teacher": "Słucha par. Wybiera dwie pary, których decyzje się różnią. Jeśli w poprzednim kroku źle odpowiedziała więcej niż 1/3 klasy, przez pierwsze  siada z tą grupą przy pytaniu „zewnętrzny czy wewnętrzny?”.", "students": "Przypadek: zamówiono 120 sztuk, przyjechało 112, a jeden karton z 12 sztukami jest uszkodzony. Każdy najpierw sam zapisuje decyzję (). Potem para porównuje decyzje i zapisuje jedną różnicę i jedną zmianę.", "device": "Jedno urządzenie na parę, tylko do zajrzenia w infografikę; decyzja na papierze."}, {"title": "Rozmowa klasy", "method": "Nauczanie dialogowe", "teacher": "Dwie pary przedstawiają różne decyzje. Nauczyciel pyta o dane: „Ile sztuk przyjmujesz bez zastrzeżeń? Co musiałoby się zmienić, żebyś podpisał dokument dostawy bez adnotacji?”", "students": "Uzasadniają decyzję liczbami z przypadku. Klucz: 100 sztuk bez zastrzeżeń; 12 uszkodzonych do reklamacji; niedobór 8 sztuk zgłoszony dostawcy; adnotacja na dokumencie dostawy przed podpisem.", "device": "Ekrany zamknięte."}, {"title": "Karta wyjścia", "method": "Metapoznanie; Przypominanie i powroty", "teacher": "Zbiera karty. Zapowiada, że za tydzień lekcja zacznie się od trzech pytań o te dokumenty.", "students": "Kończą zdanie: „Po czym rozpoznam, czy to RW, czy WZ?”", "device": "Kartka."}], "note": "Szczegółowe zasady przyjęcia dostawy zależą od procedury firmy. Materiał ZPE podaje stan prawny z 08.09.2023. Przed lekcją nauczyciel przedmiotu zawodowego sprawdza aktualność przepisów i klucz. Pięć pytań z kluczem i pełny przypadek są w opisie metody 360 e-learning.", "decision": "Punkt decyzji: jeśli po  więcej niż 1/3 klasy nie odpowiedziała na pięć pytań, rozdaj wydruk najważniejszego fragmentu i przejdź do pytania dla wszystkich."}, "variant": {"label": "Ten sam układ w przedmiocie ogólnym: matematyka, zmiana procentowa", "url": "https://zpe.gov.pl/a/obliczenia-procentowe-czesc-i/DLiy0FUq5", "rows": [["Przypomnij bez notatek", "10% z 50, 50% z 30, 1% z 400. Klucz: 5, 15, 4."], ["Pokaz jednej decyzji", "„Od jakiej liczby liczę procent?” Na przykładzie: 15% z 200 zł to 30 zł, bo podstawą jest 200 zł."], ["Praca własna z ZPE", "Przykłady z „Obliczeń procentowych”. Trzy zadania: 15% z 200 zł (30 zł); wzrost z 80 do 100 zł (o 25%); cena po obniżce o 20% wynosi 160 zł (przed obniżką: 200 zł)."], ["Jedno pytanie do wszystkich", "Cena 100 zł wzrosła o 10%, potem spadła o 10%. Ile kosztuje teraz? A) 100 zł, B) 99 zł, C) 101 zł, D) 90 zł. Poprawnie: B, bo 110 · 0,9 = 99. Typowy błąd: 100 zł."], ["Przypadek w parach", "Kurtka za 250 zł potaniała o 20%, a po miesiącu nowa cena wzrosła o 20%. Czy wróciła do 250 zł? Klucz: 200 zł, potem 240 zł, więc nie wróciła."], ["Rozmowa klasy", "Dlaczego +20% nie znosi −20%? Para wyjaśnia to jednym zdaniem: drugi procent liczy się od innej podstawy."], ["Karta wyjścia", "„Zanim policzę procent, sprawdzam…”"]]}, "devices": [["👥", "Jedno urządzenie na ucznia lub parę", "Przy pracy w parze ustal, kto obsługuje ekran, a kto zapisuje odpowiedzi. Po połowie zadania zamieńcie się rolami."], ["🔗", "Bezpośredni link", "Podaj link do fragmentu na tablicy, w dzienniku albo w kursie ZPE. Wyszukiwanie materiału przez 30 osób zabiera dużą część lekcji."], ["🔓", "Bez logowania", "Publiczny materiał ZPE otwiera się bez logowania. Logowanie uczniów jest potrzebne dopiero wtedy, gdy przypisujesz kurs i chcesz zobaczyć wyniki."], ["🧪", "Próba na tym samym sprzęcie", "Na laptopie i iPadzie materiał otwiera się w przeglądarce. Przed lekcją sprawdź jedno ćwiczenie interaktywne na takim samym urządzeniu, jakiego używają uczniowie."], ["🙈", "Ekrany w dół", "Na czas rozmowy w parach i rozmowy klasy ekrany są zamknięte: pokrywa laptopa w dół, iPad ekranem do stołu."], ["📄", "Plan B na papierze", "Wydruk wybranego fragmentu i te same pytania. Lekcja ma się odbyć także wtedy, gdy nie działa sieć."]], "methods": [["360 e-learning", "method-1.html", "Przechodzi krótki e-materiał z ćwiczeniami sprawdzanymi automatycznie, a potem rozwiązuje przypadek.", "Chodzi po sali i notuje, kto utknął; siada przy tych osobach.", "Nie nadaje się do wprowadzania całkiem nowej, trudnej treści."], ["Blended learning", "method-2.html", "Przed warsztatem rozwiązuje krótki quiz, a po kilku dniach wraca do pytania powrotnego.", "Prowadzi warsztat na tym, co wyszło w quizie.", "Liczy się to, co uczeń robi w każdej fazie, a nie liczba kanałów."], ["Flipped classroom", "method-3.html", "Przed lekcją ogląda krótki film lub fragment e-materiału i zapisuje jedno pytanie.", "Lekcję przeznacza na zadania i rozmowę o trudnościach.", "Główne ryzyko: uczniowie się nie przygotują. Plan B na papierze jest konieczny."], ["Przypominanie i powroty", "metoda-przypominanie-i-powroty.html", "Rozwiązuje ćwiczenie bez notatek, a po tygodniu wraca do tej samej treści.", "Omawia najczęstszy błąd klasy.", "Samo kliknięcie wyniku w ćwiczeniu nie wystarczy."], ["Modelowanie", "metoda-modelowanie.html", "Po krótkim pokazie rozwiązuje przykład z lukami, a potem samodzielne zadanie z materiału.", "Pokazuje procedurę, nazywa decyzje i stopniowo wycofuje pomoc.", "Sprawdź, czy e-materiał pokazuje kroki rozwiązania z komentarzem."], ["Ocenianie kształtujące", "metoda-ocenianie-ksztaltujace.html", "Odpowiada na jedno pytanie w tej samej chwili co cała klasa i poprawia pracę po wskazówce.", "Widzi odpowiedzi wszystkich i decyduje, co dalej.", "Wynik to informacja do decyzji nauczyciela, a nie ocena do dziennika."], ["Metapoznanie", "metoda-metapoznanie.html", "Przed zadaniem planuje, w trakcie sprawdza, a po zadaniu zapisuje, co zrobi inaczej.", "Pokazuje na własnym przykładzie, jak planuje i sprawdza.", "Refleksja dotyczy konkretnego zadania, a nie tego, „jak się uczyłeś”."], ["Współpraca", "metoda-wspolpraca.html", "W grupie każdy otwiera inny fragment materiału i przynosi informację potrzebną do wspólnego produktu.", "Przydziela role i sprawdza, czy każdy umie odpowiedzieć sam.", "Samo posadzenie uczniów w grupie nie daje efektu."], ["Nauczanie dialogowe", "metoda-nauczanie-dialogowe.html", "Na podstawie materiału zapisuje stanowisko i porównuje je z kolegą w parze.", "Prowadzi rozmowę klasy pytaniami o dane.", "Rozmowa odbywa się bez ekranów. Dowody są ograniczone."], ["UDL", "metoda-udl.html", "Wybiera drogę dostępu: tekst, grafikę, nagranie, powiększenie. Cel jest taki sam dla całej klasy.", "Usuwa jedną przewidywalną barierę wejścia.", "UDL nie opiera się na „stylach uczenia się”; ta koncepcja nie ma poparcia w badaniach."], ["Mastery learning", "metoda-mastery-learning.html", "Rozwiązuje krótką diagnozę. Kto opanował umiejętność, idzie dalej; kto nie, dostaje inne wyjaśnienie i ponowną próbę.", "Ustala próg i siada z grupą, która potrzebuje wyjaśnienia.", "Stosuj do jednego warunku, a nie do całego działu."], ["Problem, przypadek, projekt", "metoda-problem-projekt-przypadek.html", "Analizuje dane z materiału i podejmuje decyzję albo wykonuje produkt.", "Podaje dane etapami i pilnuje, by uczniowie uzasadniali decyzje.", "Początkujący potrzebują danych i wsparcia; odkrywanie bez wsparcia słabo działa."]], "workshop": [["Patrz, potem zrób", "Modelowanie: krótki pokaz, potem własna próba."], ["Powtórz z partnerem", "Tutoring w parach: osoba wspierająca pyta, a ćwicząca sama obsługuje komputer."], ["Przetestuj i popraw", "Ocenianie kształtujące: informacja zwrotna od partnera i poprawka."], ["Potrafię wrócić", "Przypominanie: samodzielna próba bez prowadzącego."], ["Mój następny krok", "Powroty: ponowne otwarcie materiału po 2 dniach i jego użycie po 7 dniach."]], "who": ["Kto pracuje przez większość lekcji?", "W wersji A mówi nauczyciel, a klasa słucha. W wersji B każdy uczeń pracuje z materiałem we własnym tempie. W tym czasie nauczyciel siedzi przy 3-4 osobach, które utknęły, i notuje, na którym pytaniu się zatrzymały."], "poll": {"q": "Cena 100 zł wzrosła o 10%, a potem spadła o 10%. Ile kosztuje teraz?", "options": ["100 zł", "99 zł", "101 zł", "90 zł"], "correct": 1, "explain": "110 zł · 0,9 = 99 zł. Drugi procent liczymy od nowej podstawy, czyli od 110 zł, a nie od 100 zł.", "after": "Podczas wykładu nauczyciel nie wiedziałby, ile osób uważa, że cena wróciła do 100 zł. Pytanie do wszystkich pokazuje to w kilka sekund."}, "notes": {"teza": "Około . Powiedz: „Dziś nie będzie wykładu o platformie”. Każdą z trzech kart skomentuj jednym zdaniem. Podkreśl ramkę na dole: technologia nie jest metodą.", "dwie": "Minuty 1-3. Pokaż obie osie. Zapytaj salę: „Kto pracuje przez większość lekcji?”. Odpowiedź odsłoń dopiero po 2-3 głosach. Zwróć uwagę na najdłuższy odcinek wersji B: pracę własną z materiałem.", "poll": "Minuty 3-6. Rozdaj karteczki. Odlicz do trzech: wszyscy podnoszą kartkę z literą w tej samej chwili. Policz głosy A i B i dopiero wtedy kliknij „Pokaż odpowiedź”. Powiedz: „Podczas wykładu nie wiedziałbym, ile osób myśli, że 100 zł”.", "shifts": "Slajd do lektury po warsztacie. Na żywo wskaż jedno przesunięcie najbliższe grupie, np. „nauczyciel przy uczniach”. Gdy brakuje czasu, przejdź dalej.", "lekcjaB": "Pokaż, że lekcja dzieli się na 7 krótkich etapów, a najdłuższy z nich to praca własna z materiałem. Pełny opis jest na następnym slajdzie.", "kroki": "Kliknij etap 3 (praca własna) i etap 4 (pytanie do wszystkich). Pozostałe etapy uczestnicy przejrzą sami po warsztacie.", "mat": "Dla nauczycieli przedmiotów ogólnych: ten sam układ, inna treść. Rachunki są sprawdzone.", "sprzet": "Najważniejsze są dwie rzeczy: bezpośredni link i plan B na papierze. Resztę uczestnicy przeczytają sami.", "mapa": "Nie omawiaj kart po kolei. Powiedz: „Po warsztacie kliknijcie metodę, która brzmi znajomo. Każda ma gotowy plan lekcji”.", "warsztat": "Powiedz: „Dziś Państwo są uczniami w lekcji B”. Przejdź do zadania etapu 1 (minuty 6-10)."}, "base": "https://metodyka.covepolska.pl/"}, "deck": {"label": "Warsztat dla nauczycieli · ZSZ5 · COVE Polska", "sub": "Lekcja, w której pracują uczniowie. Gotowy materiał, laptop lub iPad i czas na własną próbę.", "outcomes": ["Wybrany fragment ZPE.", "Polecenie i kryterium odpowiedzi.", "Materiał do własnej klasy.", "Instrukcje do samodzielnego powrotu."], "facts": ["4 listopada 2026", "Wspólny pokaz i praca w pracowniach", "Własny temat i gotowy materiał"], "end": [["Po 2 dniach", "Otwórz materiał przez Katalog → Ulubione."], ["Po 7 dniach", "Użyj fragmentu na lekcji albo przećwicz plan jeszcze raz."], ["Po 7-14 dniach", "Powiedz organizatorowi, co zrobili uczniowie i jakiego wsparcia potrzebujesz."]]}, "stages": [{"title": "Kto pracuje na lekcji?", "goal": "Zobaczysz, jak ZPE i laptop mogą przenieść pracę z nauczyciela na ucznia, i wybierzesz temat swojej lekcji.", "steps": ["Obejrzyj dwie wersje tej samej lekcji: wykład i lekcję z pracą własną na ZPE. Sprawdź, kto pracuje w kolejnych minutach.", "Odpowiedz na jedno pytanie jak uczeń: na kartce, w tej samej chwili co wszyscy.", "Pomyśl o lekcji, którą poprowadzisz w najbliższym tygodniu. Którą jej część uczniowie mogliby wykonać sami z materiałem?", "W „Mojej lekcji” zapisz temat i jedną rzecz, którą chcesz ułatwić uczniom."], "done": "Mam temat i wiem, którą część lekcji uczniowie mogą wykonać sami.", "hint": "Pełny wstęp z przykładową lekcją i mapą 12 metod możesz przeczytać po warsztacie. Teraz wystarczy jedno zdanie, także na papierowej karcie.", "prep": "Wyświetl wstęp „Lekcja, w której pracują uczniowie” z porównaniem dwóch wersji lekcji. Przygotuj karteczki na odpowiedź, karty pracy i sygnały pomocy.", "say": "Dziś nie będzie wykładu o platformie. Pokażę, jak może wyglądać lekcja, w której pracują uczniowie. Potem każdy przygotuje mały fragment takiej lekcji.", "run": "0-3: pokaż porównanie dwóch lekcji i zapytaj: „Kto pracuje przez większość lekcji?”. 3-6: pytanie do wszystkich: „Cena 100 zł wzrosła o 10%, potem spadła o 10%. Ile kosztuje teraz?”. Wszyscy pokazują kartkę w tej samej chwili. Policz odpowiedzi 100 zł i 99 zł. Powiedz: „Podczas wykładu nie wiedziałbym, ile osób myśli, że 100”. 6-10: uczestnicy zapisują temat i część lekcji do pracy własnej.", "error": "Uczestnik uznaje, że taka lekcja jest tylko dla informatyków, albo próbuje od razu zaplanować całą lekcję.", "help": "Wskaż jeden etap przykładowej lekcji, np.  pracy z materiałem. Zaproponuj mały fragment: ilustracja i pytanie.", "extra": "", "link": ["Zobacz przykładową lekcję", "#/wstep"]}, {"title": "Spokojny start", "goal": "Otworzysz ZPE i wrócisz do tej instrukcji.", "steps": ["Otwórz ZPE przyciskiem poniżej. Pojawi się druga karta przeglądarki.", "Na ZPE wybierz „Zaloguj się” i użyj własnych danych. Hasło wpisujesz wyłącznie w ZPE.", "Przewiń stronę kółkiem myszy lub dwoma palcami po płytce laptopa.", "Powiększ tekst w menu przeglądarki. Wróć do karty „ZPE bez pośpiechu”."], "done": "Mam otwarte ZPE i potrafię wrócić do szkolenia. Wiem, czy jestem zalogowany/zalogowana.", "hint": "Karta przeglądarki to zakładka z tytułem u góry okna. Nie zamykaj programu. Jeśli nie możesz się zalogować, zgłoś pomoc i otwórz publiczny materiał.", "prep": "Przed wejściem uczestników sprawdź Wi-Fi, projektor i otwarcie strony. Przygotuj instrukcję odzyskania dostępu w oficjalnej pomocy ZPE.", "say": "Teraz odnajdujemy dwie karty u góry. Ta karta to instrukcja, druga to miejsce ćwiczeń.", "run": "10-13: pokaż pasek adresu i karty. 13-19: logowanie. 19-22: przewijanie i powiększenie. 22-25: powrót do instrukcji i rozpoznanie potrzeb pomocy.", "error": "Adres wpisany w wyszukiwarkę zamiast paska; otwieranie wielu okien; brak hasła.", "help": "Wskaż pasek adresu, bez przejmowania myszy. Nie resetuj hasła całej grupie; uczestnik może ćwiczyć na publicznym zasobie.", "extra": "", "link": ["Otwórz ZPE", "https://zpe.gov.pl/"]}, {"title": "Patrz, potem zrób", "goal": "Znajdziesz i zapiszesz wspólny materiał.", "steps": ["Na ZPE otwórz Katalog. Wyszukaj „Gdzie tego szukać? O notowaniu”.", "Otwórz wynik o tym tytule. Odszukaj fragment o tabeli, punktach i schemacie.", "Jeśli jesteś zalogowany/zalogowana, kliknij serce „Dodaj do ulubionych”. W materiale wielostronicowym może być nad spisem treści.", "Otwórz Katalog → Ulubione i sprawdź, czy widzisz zapisany materiał. Otwórz go ponownie."], "done": "Widzę materiał w „Ulubionych” i potrafię go stamtąd otworzyć.", "hint": "Drugie kliknięcie serca może usunąć zapis. Jeśli nie znajdujesz wyniku, skorzystaj z bezpośredniego linku. Brak konta pozwala oglądać materiał, ale nie zalicza zapisu.", "prep": "Sprawdź tę ścieżkę na koncie trenera. Przygotuj kartę 2 z ilustracjami oficjalnego poradnika.", "say": "Teraz tylko patrzymy. Za chwilę każdy wykona te trzy kroki u siebie.", "run": "25-28: pokaz wyszukiwania; 28-33: wykonanie. 33-36: pokaz serca i listy; 36-42: wykonanie. 42-45: sprawdź, czy uczestnicy wrócili do zasobu przez listę.", "error": "Uczestnik zapisuje stronę w zakładkach przeglądarki albo szuka ikony bez zalogowania.", "help": "Nazwij różnicę: „Ulubione ZPE są na Twoim koncie”. Wskaż oficjalną instrukcję. Przy czterech parach z tym samym problemem powtórz pokaz.", "extra": "", "link": ["Otwórz wspólny materiał", "https://zpe.gov.pl/a/gdzie-tego-szukac-o-notowaniu/DgDem0ria"]}, {"title": "Powtórz z partnerem", "goal": "Obie osoby przećwiczą powrót do zapisanego materiału.", "steps": ["Ustalcie, kto zaczyna. Osoba A obsługuje własny laptop, osoba B czyta pytania z karty 3.", "A otwiera Ulubione, odnajduje materiał i pokazuje wybrany fragment. B pyta: „Gdzie jesteś?” i „Jaki jest następny krok?”.", "Zamieńcie role. Teraz B wykonuje te same czynności na własnym laptopie.", "Każdy samodzielnie pokaże jeden fragment i powie, co mogliby z nim zrobić uczniowie."], "done": "Każda osoba samodzielnie obsługiwała swój komputer. Oboje odnaleźliśmy materiał.", "hint": "Partner może wskazać krok w instrukcji, ale nie wykonuje go za Ciebie. Nie musicie pracować w tym samym tempie.", "prep": "Pary sąsiedzkie; karta 3. Przećwicz jedno pomocne pytanie na przykładzie.", "say": "Pomoc oznacza wskazówkę. Myszkę trzyma osoba, która teraz ćwiczy.", "run": "45-47: model pomocy. 47-54: A ćwiczy. 54-61: B ćwiczy. 61-65: indywidualny powrót i sprawdzenie efektu.", "error": "Jedna osoba wykonuje wszystkie operacje na obu komputerach.", "help": "Poproś o zmianę ról. Wróć do ostatniego kroku, który uczestnik wykonał samodzielnie.", "extra": "Szybciej gotowe? Wskaż drugi fragment tego samego materiału.", "link": null}, {"title": "Przerwa", "goal": "Odpoczniesz od ekranu.", "steps": ["Zostaw otwarte karty.", "Wstań, napij się wody i odpocznij od ekranu.", "Wróć za ."], "done": "Jestem gotowy/gotowa na dalszą część.", "hint": "Nie musisz niczego nadrabiać w przerwie.", "prep": "Zapowiedz godzinę powrotu.", "say": "Zostawiamy otwarte karty. Wracamy za dziesięć minut.", "run": "Przerwa dla całej grupy. Nie zastępuj jej obowiązkową pomocą techniczną.", "error": "Przerwa staje się kolejną częścią wykładu.", "help": "Pozostaw ekran z informacją o powrocie.", "extra": "", "link": null}, {"title": "Znajdź coś dla siebie", "goal": "Dobierzesz jeden materiał do swojej lekcji.", "steps": ["Otwórz zestaw ośmiu materiałów. Wybierz propozycję ogólną lub zawodową albo wyszukaj własny temat na ZPE.", "Sprawdź trzy rzeczy: zgodność z celem lekcji, poziom trudności i ilość treści.", "Otwórz jeden fragment, który uczeń może wykorzystać w kilka minut. Nie musisz przechodzić całego materiału.", "Zapisz zasób w Ulubionych. W swojej karcie zachowaj tytuł, link oraz nazwę fragmentu."], "done": "Mam jeden zasób i wiem, dlaczego pasuje do mojego celu.", "hint": "Jeśli po  nie masz wyniku, wybierz materiał z zestawu startowego. Link do przewodnika nauczyciela zamień na adres wybranego zasobu dla ucznia.", "prep": "Otwórz katalog startowy i wskaż podział ogólne/zawodowe. Przygotuj bezpośredni link do wspólnego przykładu.", "say": "Szukamy jednego użytecznego fragmentu. Dobry wybór to taki, do którego potrafisz ułożyć konkretne zadanie.", "run": "75-78: trzy kryteria wyboru. 78-90: wyszukiwanie. 90-95: zapis i krótkie uzasadnienie partnerowi.", "error": "Przeglądanie kolejnych materiałów bez wyboru; wybór samego przewodnika zamiast zasobu ucznia.", "help": "Po  skieruj do zestawu startowego. Zapytaj: „Który fragment pokażesz uczniowi?”.", "extra": "", "link": ["Wybierz materiał", "#/materialy"]}, {"title": "Zbuduj fragment lekcji", "goal": "Przygotujesz działanie ucznia na krótki fragment.", "steps": ["Otwórz „Moją lekcję”. Najpierw przeczytaj gotowy przykład.", "Wpisz cel, dokładny fragment i polecenie. Zacznij polecenie od „porównaj”, „wybierz”, „wyjaśnij” albo „oblicz”.", "Dopisz oczekiwaną odpowiedź i sposób sprawdzenia wszystkich uczniów.", "Rozpisz krótki fragment, łącznie ze sprawdzeniem. Zapisz plan bez internetu."], "done": "Mam cel, link, fragment, polecenie, kryterium odpowiedzi i wykonalny czas.", "hint": "„Obejrzyj film” nie określa jeszcze efektu. Dodaj: „Po obejrzeniu zapisz dwie…”. Możesz wypełnić papierową kartę zamiast formularza.", "prep": "Wyświetl gotowy przykład. Przygotuj kartę 4 i formularz. Nie korzystaj z Kreatora ZPE.", "say": "Najpierw zapiszmy, co uczeń zrobi. Dopiero potem sprawdzimy, czy materiał mu w tym pomoże.", "run": "95-100: omów model. 100-110: własne polecenie i odpowiedź. 110-117: czas, sprawdzenie i plan awaryjny. 117-120: uczestnik sprawdza kompletność z listą.", "error": "Polecenie ogranicza się do biernego oglądania; plan obejmuje zbyt wiele treści.", "help": "Poproś o jeden widoczny produkt ucznia i usuń drugie zadanie. Zostaw czas na sprawdzenie.", "extra": "", "link": ["Uzupełnij „Moją lekcję”", "#/moja-lekcja"]}, {"title": "Druga przerwa", "goal": "Odpoczniesz przed próbą własnego zadania.", "steps": ["Sprawdź komunikat zapisu formularza.", "Zostaw otwarte karty i odpocznij od ekranu.", "Wróć za ."], "done": "Wiem, gdzie jest mój plan.", "hint": "Jeśli zapis w przeglądarce nie działa, pobierz kopię tekstową lub skorzystaj z papieru.", "prep": "Zapowiedz godzinę powrotu.", "say": "Za chwilę sprawdzimy nasze polecenia na drugiej osobie.", "run": "Przerwa; nie dodawaj nowych zadań.", "error": "Uczestnik zamyka formularz mimo komunikatu o błędzie zapisu.", "help": "Pomóż pobrać kopię, potem zapewnij czas na odpoczynek.", "extra": "", "link": null}, {"title": "Przetestuj i popraw", "goal": "Sprawdzisz, czy druga osoba rozumie Twoje polecenie.", "steps": ["Runda 1: A pokazuje materiał i polecenie. B wykonuje początek zadania, A obserwuje bez dopowiadania.", "B mówi: „Wiem, co mam zrobić…” oraz „Potrzebuję doprecyzowania…”. A zapisuje jedną zmianę.", "Po  zamieńcie role.", "Każdy poprawia własne polecenie lub dobór fragmentu."], "done": "Mam jedną poprawkę wynikającą z próby z partnerem.", "hint": "Partner z innego przedmiotu sprawdza zrozumiałość instrukcji. Nie ocenia fachowej poprawności treści, których nie zna.", "prep": "Pary mają otwarte własne plany. Podaj ramę informacji zwrotnej.", "say": "Nie bronimy pierwszej wersji. Sprawdzamy, gdzie polecenie może być bardziej czytelne.", "run": "130-138: wykonanie i komentarz do planu A. 138-140: poprawka. 140-148: plan B. 148-150: poprawka.", "error": "Autor objaśnia wszystko ustnie, zanim partner spróbuje; dyskusja dotyczy gustu.", "help": "Poproś o wykonanie wyłącznie według zapisu i wskazanie konkretnego niejasnego słowa.", "extra": "", "link": ["Popraw własny plan", "#/moja-lekcja"]}, {"title": "Co można zrobić dalej?", "goal": "Rozpoznasz różnicę między linkiem a pracą w kursie.", "steps": ["Obejrzyj pokaz prowadzącego. Nie musisz powtarzać tych operacji na swoim koncie.", "Zobacz, jak materiał trafia do kursu i gdzie prowadzący odczytuje przykładowe odpowiedzi.", "Odpowiedz: czy samo skopiowanie adresu materiału daje mi raport ucznia?"], "done": "Wiem, że zwykły link nie oznacza przypisania zadania i zbierania wyników w kursie.", "hint": "Odpowiedź: nie. Kurs wymaga przygotowania i przypisania odpowiednich użytkowników. To temat na kolejne zajęcia.", "prep": "Przygotuj wcześniej kurs testowy z danymi demonstracyjnymi. Jeśli nie masz kont testowych, użyj oficjalnych ilustracji instrukcji i autorskiego przypadku poniżej. Nie prezentuj danych prawdziwych uczniów.", "say": "To pokaz możliwości na przyszłość. Dzisiaj wystarczy Wasza gotowa lekcja.", "run": "150-153: materiał → Udostępnij → Platforma edukacyjna → Nowy kurs. 153-156: wyjaśnij zapis roboczy, publikację i przypisanie. 156-159: Analiza i decyzja dydaktyczna. 159-160: pytanie kontrolne.", "error": "Uczestnicy zaczynają samodzielnie tworzyć kursy i gubią główny cel.", "help": "Zaproś do odłożenia myszy. Wyświetl link do poradnika na później.", "extra": "", "link": ["Zobacz pokaz i przykład raportu", "#/pokaz"]}, {"title": "Potrafię wrócić", "goal": "Samodzielnie odtworzysz drogę do swojego zasobu.", "steps": ["Przejdź na stronę główną ZPE. Otwórz Katalog → Ulubione.", "Odnajdź swój materiał i otwórz wybrany fragment. Możesz korzystać ze ściągi.", "Pokaż partnerowi polecenie dla ucznia i powiedz, jak sprawdzisz efekt.", "W karcie 5 zaznacz rzeczywisty poziom samodzielności. Partner potwierdza wykonanie, nie robi zadania za Ciebie."], "done": "Potrafię wrócić do zasobu albo wiem dokładnie, na którym kroku potrzebuję pomocy.", "hint": "To próba, nie konkurs. Jeśli korzystasz ze ściągi, zaznacz „ze ściągą”. Brak logowania oznacza, że zapis w Ulubionych wymaga jeszcze sprawdzenia.", "prep": "Karty 5, lista obserwacji trenera. Najpierw odwiedź stanowiska zgłaszające trudność.", "say": "Zaczynamy od strony głównej. Tym razem każdy przechodzi drogę sam.", "run": "160-168: indywidualna próba. 168-172: potwierdzenie partnera i pomoc. 172-175: ponowna próba trudnego kroku oraz samoocena.", "error": "Za dowód uznaje się otwartą wcześniej kartę lub deklarację bez wykonania.", "help": "Poproś o powrót przez listę Ulubionych. Zapisz potrzebę pomocy; nie oznaczaj automatycznie sukcesu.", "extra": "", "link": ["Otwórz sprawdzenie końcowe", "#/sprawdzenie"]}, {"title": "Mój następny krok", "goal": "Zaplanujesz pierwsze wykorzystanie i powtórkę.", "steps": ["W „Mojej lekcji” wpisz datę i klasę pierwszego wykorzystania.", "Wydrukuj plan lub pobierz kopię tekstową. Sprawdź, czy zawiera link.", "Oddaj trenerowi papierową kartę końcową. Zapisy na tej stronie pozostają w Twojej przeglądarce.", "Po 2 dniach ponownie otwórz materiał. Po 7 dniach użyj go na lekcji lub przećwicz plan."], "done": "Mam zachowany plan i konkretny termin wykorzystania.", "hint": "Nie musisz wdrażać wszystkich funkcji ZPE. Powtórz tę samą krótką drogę do jednego materiału.", "prep": "Przygotuj miejsce odbioru kart końcowych i termin zebrania informacji po 7-14 dniach.", "say": "Dokończ zdanie: wykorzystam ten fragment w klasie… w dniu…", "run": "175-177: termin. 177-179: zapis lub wydruk. 179-180: zebranie kart. Zapowiedz trzy pytania po wdrożeniu.", "error": "Ogólna deklaracja „kiedyś skorzystam”; przekonanie, że trener automatycznie widzi formularz.", "help": "Poproś o termin i pokaż pobieranie kopii. Wyjaśnij, że strona niczego nie wysyła.", "extra": "", "link": ["Zachowaj własny plan", "#/moja-lekcja"]}], "preflight": ["Sprawdź logowanie, wyszukiwanie, Ulubione i ponowne otwarcie na koncie trenera.", "Przetestuj udostępnienie i rejestrowanie odpowiedzi na kontach testowych. Nie pokazuj danych uczniów.", "Sprawdź projektor, internet i stanowiska w pracowniach na trzecim piętrze.", "Poproś uczestników o własny temat i dostępne materiały. Hasła wpisują wyłącznie w ZPE.", "Przygotuj wydruki na wypadek problemów technicznych."], "checks": ["Odnajduję materiał pasujący do tematu.", "Zapisuję materiał w Ulubionych na swoim koncie.", "Otwieram go ponownie przez Katalog → Ulubione.", "Wskazuję dokładny fragment i polecenie dla ucznia.", "Wyjaśniam, jak sprawdzę odpowiedź ucznia."], "statuses": ["Wykonuję samodzielnie", "Wykonuję ze ściągą", "Potrzebuję pomocy"], "prepared_date": "27.10.2026"};
